"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/** What the voice assistant is doing. */
export type VoiceOrbState = "idle" | "listening" | "thinking" | "speaking";

/** Props for a voice orb. */
export type VoiceOrbProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  state?: VoiceOrbState;
  /** How loud the microphone input is, from 0 to 1. Only the listening state reads it. */
  level?: number;
  /** The words under the orb for each state. Replace any of them. */
  labels?: Partial<Record<VoiceOrbState, string>>;
};

const LABELS = {
  idle: "Ready",
  listening: "Listening",
  thinking: "Thinking",
  speaking: "Speaking",
} satisfies Record<VoiceOrbState, string>;

// Damping 35 is just over 2 × √300: the orb follows the voice and never rings after it.
const LEVEL_SPRING: Transition = { type: "spring", stiffness: 300, damping: 35, mass: 1 };
// Breathing and pulsing go there and back, so they ease both ways.
const BREATH: Transition = { duration: 4, ease: "easeInOut", repeat: Infinity };
const PULSE: Transition = { duration: 1.2, ease: "easeInOut", repeat: Infinity };
// Rotation that never stops has no start to ease out of.
const SWIRL: Transition = { duration: 3, ease: "linear", repeat: Infinity };
const RIPPLE: Transition = { duration: 1.2, ease: [0.165, 0.84, 0.44, 1], repeat: Infinity };
const SETTLE: Transition = { duration: 0.4, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };

/**
 * A flat disc that shows the state of a voice assistant. It breathes when
 * idle, swells with the voice while listening, turns an open ring while
 * thinking and pulses while speaking. The label under it says the state in
 * words, so the shape is never the only signal.
 */
export function VoiceOrb({ state = "idle", level = 0, labels, className, ...divProps }: VoiceOrbProps) {
  const reduceMotion = useReducedMotion();
  const loud = Math.min(1, Math.max(0, Number.isFinite(level) ? level : 0));
  const label = labels?.[state] ?? LABELS[state];

  const body = reduceMotion
    ? { animate: { scale: 1 }, transition: INSTANT }
    : {
        idle: { animate: { scale: [1, 1.04, 1] }, transition: BREATH },
        listening: { animate: { scale: 1 + loud * 0.25 }, transition: LEVEL_SPRING },
        thinking: { animate: { scale: 0.96 }, transition: SETTLE },
        speaking: { animate: { scale: [1, 1.1, 0.98, 1.06, 1] }, transition: PULSE },
      }[state];
  const swirling = state === "thinking" && !reduceMotion;
  const glow = state === "listening" ? 0.35 + loud * 0.65 : state === "idle" ? 0.35 : 0.6;

  return (
    <div {...divProps} data-state={state} className={cn("inline-flex flex-col items-center gap-4", className)}>
      <div aria-hidden="true" className="relative grid size-28 place-items-center">
        {state === "speaking" && !reduceMotion && (
          <motion.span
            initial={{ scale: 1, opacity: 0.4 }}
            animate={{ scale: 1.35, opacity: 0 }}
            transition={RIPPLE}
            className="absolute inset-2 rounded-full border border-primary/60"
          />
        )}
        <motion.div {...body} className="relative size-24">
          {/* The halo: a flat, pale ring behind the body that brightens with the voice. */}
          <motion.span
            initial={false}
            animate={{ opacity: glow }}
            transition={reduceMotion ? INSTANT : LEVEL_SPRING}
            className="absolute -inset-2 rounded-full bg-primary/25"
          />
          <span className="absolute inset-0 rounded-full bg-primary" />
          {/* The swirl: an open ring that shows only while thinking, so that state has its own shape and movement. */}
          {state === "thinking" && (
            <motion.span
              initial={false}
              animate={{ rotate: swirling ? 360 : 0 }}
              transition={swirling ? SWIRL : INSTANT}
              className="absolute inset-4 rounded-full border-2 border-primary-foreground border-t-transparent"
            />
          )}
        </motion.div>
      </div>
      <p role="status" className="text-sm font-medium text-foreground">
        {label}
      </p>
    </div>
  );
}
